-- Tam sayı sütunlarında kalmış ondalık değerleri onarır.
--
-- Bu sütunlar bulutta integer/bigint. Yerelde SQLite ondalığı sessizce
-- kabul ediyordu: vardiya sonunda "238,5" yazılan kilometre cihazda
-- real olarak durdu, gönderimde Postgres reddetti ve tablo tek istekte
-- gittiği için o tablonun bütün yedeği takıldı. Yazma yolları artık
-- tam sayı yazıyor; burada daha önce yazılmış olanlar düzeltiliyor.
--
-- SQLite ROUND sıfırdan uzağa yarım yuvarlıyor (2,5 → 3), para ile aynı
-- kural. updated_at BİR ARTAR: bu sürüm buluta hiç ulaşamadı, onarılan
-- satır yeni bir düzeltme gibi gitmeli.
--
-- SIRA ÖNEMLİ: önce kuyruk, sonra onarım — onarımdan sonra hangi satırın
-- ondalık olduğu artık görülemez. Takılmış kuyruk kaydının denemesi de
-- sıfırlanır; bekleme süresi dolmadan yeniden gitsin.
INSERT INTO `outbox` (`table_name`, `row_id`, `user_id`, `operation`, `revision`, `attempt_count`, `created_at`)
SELECT 'app_settings', `id`, `user_id`, CASE WHEN `deleted_at` IS NULL THEN 'upsert' ELSE 'delete' END, 1, 0, CAST(strftime('%s', 'now') AS INTEGER) * 1000
FROM `app_settings` WHERE typeof(`created_at`) = 'real' OR typeof(`updated_at`) = 'real' OR typeof(`deleted_at`) = 'real' OR typeof(`day_cutoff_hour`) = 'real' OR typeof(`onboarding_completed_at`) = 'real'
ON CONFLICT (`table_name`, `row_id`) DO UPDATE SET `operation` = excluded.`operation`, `user_id` = excluded.`user_id`, `revision` = `outbox`.`revision` + 1, `attempt_count` = 0, `last_error` = NULL, `next_attempt_at` = NULL;
