WHERE typeof(`created_at`) = 'real' OR typeof(`updated_at`) = 'real' OR typeof(`deleted_at`) = 'real' OR typeof(`day_cutoff_hour`) = 'real' OR typeof(`onboarding_completed_at`) = 'real';
